for _k, _v in EXTRA.items(): QUESTIONS[_k] += _v
def main():
    rows = [(q, i, RESPONSES[i] + (NOTE if i != "greeting" else "")) for i, qs in QUESTIONS.items() for q in qs]
    with open(os.path.join(HERE, "college_faq_dataset.csv"), "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f); w.writerow(["question", "intent", "answer"]); w.writerows(rows)
    json.dump({k: v + (NOTE if k != "greeting" else "") for k, v in RESPONSES.items()},
              open(os.path.join(HERE, "responses.json"), "w"), indent=2)
    print(f"Wrote {len(rows)} questions across {len(QUESTIONS)} intents")
if __name__ == "__main__": main()
